text:
{
  "design": {
    "theme": "chalk",
    "picture_style": "photo"
  },
  "flow": [
    {"slide": 1, "does": "Recall familiar adult animals", "look_at": {"kind": "picture", "shows": "A cow, sheep, hen and dog"}, "teaches": []},
    {"slide": 2, "does": "Introduce the learning goals", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Model naming two adult–young pairs", "look_at": {"kind": "picture", "shows": "A cow with a calf and a sheep with a lamb"}, "teaches": [1]},
    {"slide": 4, "does": "Try naming the same pairs", "look_at": {"kind": "picture", "shows": "A cow, calf, sheep and lamb in a mixed arrangement"}, "teaches": [1]},
    {"slide": 5, "does": "Model naming two more pairs", "look_at": {"kind": "picture", "shows": "A hen with a chick and a dog with a puppy"}, "teaches": [1]},
    {"slide": 6, "does": "Try naming the same pairs", "look_at": {"kind": "picture", "shows": "A hen, chick, dog and puppy in a mixed arrangement"}, "teaches": [1]},
    {"slide": 7, "does": "Predict changes as a chick grows", "look_at": {"kind": "picture", "shows": "A small chick with fluffy down"}, "teaches": [2]},
    {"slide": 8, "does": "Teach changes from chick to hen", "look_at": {"kind": "picture-sequence", "shows": "A chick grows bigger and develops adult feathers"}, "teaches": [2]},
    {"slide": 9, "does": "Correct the idea that young are tiny copies", "look_at": {"kind": "picture", "shows": "Differences between a chick and an adult hen"}, "teaches": [2]},
    {"slide": 10, "does": "Check understanding of growth", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 11, "does": "Apply growth ideas to a new hen", "look_at": {"kind": "picture", "shows": "An adult brown hen with clear wing and tail feathers"}, "teaches": [2]},
    {"slide": 12, "does": "Check all animal pairs before the worksheet exit ticket", "look_at": {"kind": "picture", "shows": "All four adults and their young, mixed up"}, "teaches": [1]}
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name the animals you know.",
    "picture": {
      "shows": "Four separate photographs of a cow, sheep, hen and dog",
      "must_see": ["adult cow", "adult sheep", "adult hen", "adult dog"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "compare",
      "heading": "Adults and their young",
      "columns": [
        {
          "label": "Cow and calf",
          "text": "A calf is a young cow.",
          "picture": {
            "shows": "An adult cow standing beside its calf",
            "must_see": ["adult cow", "small calf"],
            "subject": "generic"
          }
        },
        {
          "label": "Sheep and lamb",
          "text": "A lamb is a young sheep.",
          "picture": {
            "shows": "An adult sheep standing beside its lamb",
            "must_see": ["adult sheep", "small lamb"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the pairs",
      "questions": [
        "Which young animal goes with the cow?",
        "Which young animal goes with the sheep?",
        "What are the young animals called?"
      ],
      "instruction": "Point to each pair. Say its names.",
      "picture": {
        "shows": "Separate photographs arranged calf, sheep, cow, lamb, without pairing cues",
        "must_see": ["small calf", "adult sheep", "adult cow", "small lamb"],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "Two more pairs",
      "columns": [
        {
          "label": "Hen and chick",
          "text": "A chick is a young chicken.",
          "picture": {
            "shows": "An adult hen beside a newly hatched chick",
            "must_see": ["adult hen", "fluffy chick"],
            "subject": "generic"
          }
        },
        {
          "label": "Dog and puppy",
          "text": "A puppy is a young dog.",
          "picture": {
            "shows": "An adult dog beside a young puppy of the same breed",
            "must_see": ["adult dog", "small puppy"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the pairs",
      "questions": [
        "Which young animal goes with the hen?",
        "Which young animal goes with the dog?",
        "What are the young animals called?"
      ],
      "instruction": "Point to each pair. Say its names.",
      "picture": {
        "shows": "Separate photographs arranged puppy, hen, dog, chick, without pairing cues",
        "must_see": ["small puppy", "adult hen", "adult dog", "fluffy chick"],
        "subject": "generic"
      }
    },
    {
      "template": "discussion",
      "heading": "What might change?",
      "lead": "Tell a partner: how might this chick change as it grows?",
      "picture": {
        "shows": "A newly hatched female chick standing in profile",
        "must_see": ["small body", "fluffy down", "short wings"],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows into a hen",
      "sequence": [
        {
          "shows": "A newly hatched female chick with fluffy down, before adult wing and tail feathers have developed",
          "must_see": ["small body", "fluffy down", "short wings"],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "A larger young female chicken with emerging wing feathers and some remaining down, before a full adult tail has developed",
          "must_see": ["larger body", "new wing feathers", "remaining fluffy down"],
          "subject": "generic",
          "caption": "Bigger; feathers grow"
        },
        {
          "shows": "A fully grown hen of the same breed with adult wing and tail feathers",
          "must_see": ["full grown body", "adult wing feathers", "adult tail feathers"],
          "subject": "generic",
          "caption": "Hen with adult feathers"
        }
      ]
    },
    {
      "template": "compare",
      "heading": "Not just a tiny hen",
      "columns": [
        {
          "label": "Chick",
          "text": "Small, with fluffy down.",
          "picture": {
            "shows": "A newly hatched female chick in profile",
            "must_see": ["small body", "fluffy down", "short wings"],
            "subject": "generic"
          }
        },
        {
          "label": "Hen",
          "text": "Bigger, with adult feathers.",
          "picture": {
            "shows": "An adult hen of the same breed in profile, at the same photographic scale as the chick",
            "must_see": ["larger body", "long wing feathers", "adult tail feathers"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "hinge",
      "heading": "Choose one",
      "stem": "What happens as a chick grows into a hen?",
      "options": [
        "It only gets bigger.",
        "It gets bigger and grows adult feathers.",
        "It stays small and fluffy."
      ],
      "correct": 2
    },
    {
      "template": "question-set",
      "heading": "Think back in time",
      "questions": [
        "What was this hen called when it was young?",
        "How was its size different?",
        "How were its feathers different?"
      ],
      "instruction": "Imagine this hen as a baby. Explain.",
      "picture": {
        "shows": "A brown adult hen in profile, a different example from the growth sequence",
        "must_see": ["adult brown hen", "layered wing feathers", "long tail feathers"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "Name and match",
      "questions": [
        "Name each adult animal.",
        "Find its young animal.",
        "Say both names in each pair."
      ],
      "instruction": "Find all four pairs on your own.",
      "picture": {
        "shows": "Eight separate photographs in two mixed rows: dog, lamb, hen, calf; chick, cow, puppy, sheep; no matching cues",
        "must_see": [
          "adult dog",
          "small lamb",
          "adult hen",
          "small calf जम"
        ],
        "subject": "generic"
      }
    }
  ]
}
